INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A yarn is spun to 30s Ne (30 hanks of 840 yards per pound). Approximately how many yards of this yarn would weigh one pound?', '["25,200 yards","8,400 yards","840 yards","30 yards"]'::jsonb, '25,200 yards', 'In Ne count, total yards per pound = count × 840 yards. So 30s Ne = 30 × 840 = 25,200 yards per pound.', 2, '{"yarn-count-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Two 20s Ne single yarns are twisted together (plied) to make a 2-ply yarn. What is the approximate resultant count of the plied yarn?', '["10s Ne","20s Ne","40s Ne","2s Ne"]'::jsonb, '10s Ne', 'For plying, resultant count ≈ single count ÷ number of plies (since Ne is inverse to weight per length). Two 20s singles plied give roughly 20/2 = 10s Ne — the ply is coarser than either single.', 2, '{"ply-count"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'If a draw frame applies a draft of 6 to an input sliver of hank 0.12 Ne, what is the approximate output sliver hank?', '["0.72 Ne","0.02 Ne","6.12 Ne","0.12 Ne"]'::jsonb, '0.72 Ne', 'Output hank = input hank × draft (since drafting reduces linear density proportionally, increasing the count number). 0.12 × 6 = 0.72 Ne.', 2, '{"draft-calculation"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A ring frame spindle rotates at 15,000 rpm and the desired twist is 20 turns per inch. Approximately what yarn delivery speed (inches per minute) does this imply?', '["750 inches/min","15,020 inches/min","300,000 inches/min","20 inches/min"]'::jsonb, '750 inches/min', 'Delivery speed = spindle rpm ÷ TPI = 15,000 ÷ 20 = 750 inches per minute — since each inch of yarn needs 20 spindle rotations to insert 20 twists.', 2, '{"twist-calculation"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why does increasing the draft at the draw frame beyond the machine''s designed capability typically worsen yarn/sliver evenness rather than improve it?', '["Excessive draft causes uncontrolled ''floating fibers'' that aren''t properly gripped by rollers, causing drafting waves and irregularity","Higher draft always improves evenness with no limit","Draft has no relationship to evenness","Draft only affects color, not evenness"]'::jsonb, 'Excessive draft causes uncontrolled ''floating fibers'' that aren''t properly gripped by rollers, causing drafting waves and irregularity', 'Beyond an optimum draft, fibers not fully controlled by either the front or back roller (''floating fibers'') move unpredictably, creating drafting waves — periodic thick/thin irregularities — rather than even attenuation.', 2, '{"drafting-waves"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why is combing typically only economical/common for finer cotton counts (e.g., above ~40s Ne) rather than very coarse yarns?', '["The extra cost of removing short fiber (noil) is justified by the quality/fineness gain needed for fine yarns, but not worth it for coarse yarns","Combing machines physically cannot process coarse fiber at all","Coarse yarns cannot be spun from any cotton fiber","Combing always makes yarn weaker regardless of count"]'::jsonb, 'The extra cost of removing short fiber (noil) is justified by the quality/fineness gain needed for fine yarns, but not worth it for coarse yarns', 'Combing is a costly extra step (fiber loss as noil, added machine time) that yields better evenness/strength — valuable for fine, high-quality yarns where a few extra short fibers cause disproportionate problems, but not cost-effective for coarse, everyday yarns.', 2, '{"combing-economics"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A spinning mill notices increased end breakage at the ring frame after switching to a slightly lower-twist yarn recipe. What is the most likely direct cause?', '["Lower twist reduces inter-fiber friction/cohesion, lowering yarn strength and making it more prone to breaking under spinning tension","Lower twist always increases yarn strength, so this shouldn''t happen","Twist level has no effect on yarn strength","The ring frame speed automatically compensates for twist changes"]'::jsonb, 'Lower twist reduces inter-fiber friction/cohesion, lowering yarn strength and making it more prone to breaking under spinning tension', 'Within the normal operating range, less twist means less fiber-to-fiber gripping force, so the yarn has lower tenacity — under the same spinning tension, this leads to more end breaks.', 2, '{"twist","end-breakage"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why does a traveler that is too heavy (high mass) for the yarn count being spun tend to cause more yarn breakage?', '["A heavier traveler creates more tension/drag on the yarn as it''s dragged around the ring, exceeding the yarn''s strength","A heavier traveler always reduces tension on the yarn","Traveler weight has no effect on yarn tension","Heavier travelers automatically reduce twist to compensate"]'::jsonb, 'A heavier traveler creates more tension/drag on the yarn as it''s dragged around the ring, exceeding the yarn''s strength', 'The traveler is dragged around the ring by yarn tension; a traveler too heavy for the yarn''s strength creates excessive tension, which can exceed the yarn''s breaking strength, especially at weak spots.', 2, '{"traveler-weight"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A cotton batch has a lower micronaire value than usual (finer/less mature fiber) for the same variety. What spinning consequence is most likely?', '["Potentially more neps and processing difficulty, but ability to spin finer yarns if maturity is adequate","No change in any spinning parameter","Automatically higher yarn strength with no downsides","The fiber becomes unspinnable entirely"]'::jsonb, 'Potentially more neps and processing difficulty, but ability to spin finer yarns if maturity is adequate', 'Finer fiber (lower micronaire) can enable finer yarn counts, but if it also reflects immaturity, the fiber is weaker and more prone to neps/breakage during processing — so the outcome depends on whether fineness is due to true fineness or immaturity.', 2, '{"micronaire","cotton-quality"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'In rotor (open-end) spinning, what causes the characteristic ''wrapper fibers'' on the yarn surface?', '["Some fibers wrap around the yarn body due to the rotor''s peeling/twisting action rather than aligning parallel along the yarn axis","Wrapper fibers are added intentionally by a separate feeding mechanism","They come from dye particles adhering to the yarn","They result from the ring-traveler twisting mechanism"]'::jsonb, 'Some fibers wrap around the yarn body due to the rotor''s peeling/twisting action rather than aligning parallel along the yarn axis', 'In the rotor, fiber is peeled from the rotor groove and twisted into the yarn tail; some fibers end up wrapping around the yarn''s circumference rather than lying parallel to its axis, creating the characteristic wrapper-fiber surface structure unique to rotor yarn.', 2, '{"rotor-spinning","wrapper-fibers"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why does rotor-spun yarn generally have LOWER tenacity than ring-spun yarn of the same count and fiber, despite often appearing bulkier?', '["Wrapper fibers and less-controlled fiber orientation reduce efficient load-bearing fiber alignment compared to the highly parallel structure of ring yarn","Rotor yarn always has more twist than ring yarn, which reduces strength","Ring yarn has no twist at all, so comparison is invalid","Rotor-spun fiber is always shorter than ring-spun fiber by definition"]'::jsonb, 'Wrapper fibers and less-controlled fiber orientation reduce efficient load-bearing fiber alignment compared to the highly parallel structure of ring yarn', 'Ring spinning produces a more compact, parallel-fiber structure that efficiently shares load; rotor yarn''s wrapper fibers and looser core structure mean not all fibers contribute efficiently to strength, lowering overall tenacity despite similar or higher bulk.', 2, '{"rotor-vs-ring"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A spinner wants to reduce yarn hairiness without changing the yarn count. Which adjustment is most directly relevant?', '["Increasing twist level (within limits) to bind protruding fiber ends more tightly into the yarn body","Switching to a coarser traveler size only","Reducing the number of drawing passages","Increasing roving twist only, leaving ring-frame twist unchanged"]'::jsonb, 'Increasing twist level (within limits) to bind protruding fiber ends more tightly into the yarn body', 'Higher twist binds fiber ends more tightly into the yarn structure, reducing the number of loose protruding fiber ends (hairiness) — though too much twist causes other problems like harsh handle and ''snarling''.', 2, '{"hairiness","twist"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why is ''doubling'' (combining multiple slivers) at the draw frame effective at reducing count irregularity, even though each individual sliver may be uneven?', '["Random thick/thin spots in different slivers tend to average out statistically when several slivers are combined","Doubling always eliminates all fiber, leaving only average mass","Doubling has no statistical effect on evenness","Doubling only works if every input sliver is already perfectly even"]'::jsonb, 'Random thick/thin spots in different slivers tend to average out statistically when several slivers are combined', 'This is the statistical ''doubling law'': if irregularities in different slivers are independent/random, combining n slivers reduces the resultant CV% by roughly the square root of n, since local thick and thin spots tend to cancel out.', 2, '{"doubling","evenness"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A quality control report shows yarn count CV% has increased significantly this week compared to baseline, with no change in draft settings. What is a plausible root cause to investigate first?', '["Roller/apron wear or slippage in the drafting system causing inconsistent draft control","The yarn''s twist direction (S or Z)","The color of the dye used","The packaging material of the finished cones"]'::jsonb, 'Roller/apron wear or slippage in the drafting system causing inconsistent draft control', 'Since nominal draft settings haven''t changed, increased count variation points to a mechanical issue in the actual drafting process — worn or slipping rollers/aprons fail to control fiber movement consistently, causing irregular attenuation even with unchanged settings.', 2, '{"troubleshooting","count-cv"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why does spinning very fine yarn counts (e.g., 100s Ne) generally require longer-staple, higher-quality cotton than spinning coarse counts (e.g., 10s Ne)?', '["Fine yarns have fewer fibers in their cross-section, so each fiber''s length/strength contribution matters more for adequate yarn strength","Fine yarns always use more fiber overall than coarse yarns","Fiber quality has no relationship to achievable yarn fineness","Coarse yarns require longer fiber than fine yarns"]'::jsonb, 'Fine yarns have fewer fibers in their cross-section, so each fiber''s length/strength contribution matters more for adequate yarn strength', 'A fine yarn''s cross-section contains far fewer fibers than a coarse yarn of the same fiber type. With fewer fibers to share the load and create cohesion, each fiber''s length (for gripping) and strength matter proportionally more — hence the need for higher-quality, longer-staple cotton for fine counts.', 2, '{"fiber-quality","yarn-fineness"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is the main reason ''sliver lap'' or ''ribbon lap'' machines exist as a step before combing, rather than feeding card sliver directly to the comber?', '["The comber requires a properly formed, uniform lap (flat sheet) rather than a round sliver for correct fiber presentation and gripping","Lap formation is purely for cosmetic/packaging purposes with no functional role","The comber cannot process any fiber that hasn''t been dyed first","Lap machines exist only to add twist before combing"]'::jsonb, 'The comber requires a properly formed, uniform lap (flat sheet) rather than a round sliver for correct fiber presentation and gripping', 'The combing cylinder needs to grip a flat, uniform sheet (lap) of fiber correctly to comb it effectively; round card/draw sliver isn''t suitable feed material, so lap-forming machines convert slivers into the flat lap format the comber requires.', 2, '{"lap-formation","combing-prep"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A mill compares two yarn batches with identical count and twist, but Batch A used only virgin cotton while Batch B blended in 20% recycled cotton fiber. Batch B shows lower strength and higher hairiness. What is the most likely underlying reason?', '["Recycled/reprocessed cotton fiber is typically shorter and more damaged from the mechanical reclaiming process, reducing fiber-to-fiber cohesion","Recycled cotton fiber is always chemically different from virgin cotton","Twist level automatically changes when recycled fiber is blended in","Recycled cotton cannot physically be spun into any yarn"]'::jsonb, 'Recycled/reprocessed cotton fiber is typically shorter and more damaged from the mechanical reclaiming process, reducing fiber-to-fiber cohesion', 'Mechanical recycling (tearing/shredding) shortens and damages fibers; shorter, weaker fibers reduce the yarn''s overall strength and increase hairiness (more fiber ends protrude since shorter fibers are harder to fully bind into the twisted structure).', 2, '{"recycled-cotton"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why does the ring rail''s traverse (up-down) motion typically build a yarn package with a slightly conical/tapered shape at each end (a ''cop'' build) rather than a simple cylinder?', '["The controlled traverse pattern builds layers with a specific taper to ensure the package holds together and unwinds smoothly during later processing","The taper is an unavoidable manufacturing defect with no functional purpose","Cop shape has no relationship to the traverse motion at all","It results entirely from twist level, not traverse motion"]'::jsonb, 'The controlled traverse pattern builds layers with a specific taper to ensure the package holds together and unwinds smoothly during later processing', 'The ring rail''s traverse motion is deliberately controlled (often with a shortening stroke) to build a cop with a defined base and taper, which keeps the package stable and allows smooth over-end unwinding during subsequent winding.', 2, '{"ring-frame","cop-build"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A spinner increases the speed frame (simplex) roving twist significantly to reduce roving breakage during transport. What is a likely downside at the ring frame?', '["Excess roving twist can resist drafting at the ring frame, causing uneven drafting and potential yarn irregularity","Higher roving twist always makes ring-frame drafting easier with no downside","Roving twist has no relationship to ring-frame drafting performance","It automatically improves final yarn evenness with no tradeoff"]'::jsonb, 'Excess roving twist can resist drafting at the ring frame, causing uneven drafting and potential yarn irregularity', 'Roving twist should be just enough to give the roving handling strength; too much twist makes the roving resist the drafting rollers'' attenuation, potentially causing uneven, poorly controlled drafting and resultant yarn irregularity at the ring frame.', 2, '{"roving-twist","draft-resistance"}'::text[]);
